55	/****************************************************************************
56	 * Name: bk7258_prioritize_syscall
57	 *
58	 * Description:
59	 *   Give SVCall its own priority.  Needed even when prioritised interrupt
60	 *   support is not configured, because BASEPRI masking relies on SVCall
61	 *   sitting above the masked range.
62	 *
63	 ****************************************************************************/
64	
65	static inline void bk7258_prioritize_syscall(int priority)
66	{
67	  uint32_t regval;
68	
69	  /* SVCall is system handler 11 */
70	
71	  regval  = getreg32(NVIC_SYSH8_11_PRIORITY);
72	  regval &= ~NVIC_SYSH_PRIORITY_PR11_MASK;
73	  regval |= (uint32_t)priority << NVIC_SYSH_PRIORITY_PR11_SHIFT;
74	  putreg32(regval, NVIC_SYSH8_11_PRIORITY);
75	}
