77	/****************************************************************************
78	 * Name: bk7258_exception_bit
79	 *
80	 * Description:
81	 *   Map one of the maskable processor exceptions onto the register and bit
82	 *   that controls it.  Returns ERROR for exceptions that cannot be masked.
83	 *
84	 ****************************************************************************/
85	
86	static int bk7258_exception_bit(int irq, uintptr_t *regaddr, uint32_t *bit)
87	{
88	  *regaddr = NVIC_SYSHCON;
89	
90	  switch (irq)
91	    {
92	      case NVIC_IRQ_MEMFAULT:
93	        *bit = NVIC_SYSHCON_MEMFAULTENA;
94	        break;
95	
96	      case NVIC_IRQ_BUSFAULT:
97	        *bit = NVIC_SYSHCON_BUSFAULTENA;
98	        break;
99	
100	      case NVIC_IRQ_USAGEFAULT:
101	        *bit = NVIC_SYSHCON_USGFAULTENA;
102	        break;
103	
104	      case NVIC_IRQ_SYSTICK:
105	        *regaddr = NVIC_SYSTICK_CTRL;
106	        *bit     = NVIC_SYSTICK_CTRL_ENABLE;
107	        break;
108	
109	      default:
110	        return ERROR;
111	    }
112	
113	  return OK;
114	}
