121	 * Name: up_irqinitialize
122	 ****************************************************************************/
123	
124	void up_irqinitialize(void)
125	{
126	  int num_priority_registers;
127	  uintptr_t regaddr;
128	  int i;
129	
130	  /* Disable and clear every peripheral interrupt. */
131	
132	  for (i = 0; i < BK7258_IRQ_NEXTINTS; i += 32)
133	    {
134	      putreg32(0xffffffff, NVIC_IRQ_CLEAR(i));
135	      putreg32(0xffffffff, NVIC_IRQ_CLRPEND(i));
136	    }
137	
138	  /* Point the NVIC at our vector table. */
139	
140	  putreg32((uint32_t)_vectors, NVIC_VECTAB);
141	
142	#ifdef CONFIG_ARCH_RAMVECTORS
143	  up_ramvec_initialize();
144	#endif
145	
146	  /* Give the configurable system exceptions the default priority. */
147	
148	  putreg32(DEFPRIORITY32, NVIC_SYSH4_7_PRIORITY);
149	  putreg32(DEFPRIORITY32, NVIC_SYSH8_11_PRIORITY);
150	  putreg32(DEFPRIORITY32, NVIC_SYSH12_15_PRIORITY);
151	
152	  /* NVIC_ICTR bits 0-4 report how many 32-line blocks the NVIC implements,
153	   * which is eight priority registers per block.
154	   */
155	
156	  num_priority_registers = (getreg32(NVIC_ICTR) + 1) * 8;
157	
158	  regaddr = NVIC_IRQ0_3_PRIORITY;
159	  while (num_priority_registers--)
160	    {
161	      putreg32(DEFPRIORITY32, regaddr);
162	      regaddr += 4;
163	    }
164	
165	  /* Catch memory management faults so a bad access reports instead of
166	   * silently escalating to a hard fault.
167	   */
168	
169	#ifdef CONFIG_ARM_MPU
170	  up_enable_irq(NVIC_IRQ_MEMFAULT);
171	#endif
172	
173	#ifdef CONFIG_DEBUG_FEATURES
174	  modifyreg32(NVIC_SYSHCON, 0,
175	              NVIC_SYSHCON_USGFAULTENA | NVIC_SYSHCON_BUSFAULTENA |
176	              NVIC_SYSHCON_MEMFAULTENA);
177	#endif
178	
179	  /* Attach the SVCall and hard fault handlers.  Setting the SVCall priority
180	   * below is not enough on its own: without these two attaches the vector
181	   * slots still hold irq_unexpected_isr, and the very first context switch
182	   * raises SVCall.  The symptom of leaving them out is a shell that prints
183	   * its banner and then ignores every keystroke -- boot-time code runs, but
184	   * any wakeup that needs the scheduler dies in "ERROR irq: 11".
185	   */
186	
187	  irq_attach(NVIC_IRQ_SVCALL, arm_svcall, NULL);
188	  irq_attach(NVIC_IRQ_HARDFAULT, arm_hardfault, NULL);
189	
190	  /* SVCall has to stay above the BASEPRI mask level. */
191	
192	  bk7258_prioritize_syscall(NVIC_SYSH_SVCALL_PRIORITY);
193	
194	#ifndef CONFIG_SUPPRESS_INTERRUPTS
195	  up_irq_enable();
196	#endif
197	}
