200	 * Name: up_disable_irq
201	 ****************************************************************************/
202	
203	void up_disable_irq(int irq)
204	{
205	  uintptr_t regaddr;
206	  uint32_t regval;
207	  uint32_t bit;
208	  int n;
209	
210	  DEBUGASSERT(irq >= NVIC_IRQ_NMI && irq < NR_IRQS);
211	
212	  if (irq >= NVIC_IRQ_FIRST)
213	    {
214	      /* The clear-enable registers are write-1-to-clear. */
215	
216	      n = irq - NVIC_IRQ_FIRST;
217	      putreg32((uint32_t)1 << (n & 0x1f), NVIC_IRQ_CLEAR(n));
218	
219	      /* Take the line out of the SoC routing matrix as well; see
220	       * up_enable_irq() for why the matrix exists.
221	       */
222	
223	      modifyreg32(BK7258_SYS_CPU0_INT_EN(n), (uint32_t)1 << (n & 0x1f), 0);
224	    }
225	  else if (bk7258_exception_bit(irq, &regaddr, &bit) == OK)
226	    {
227	      regval  = getreg32(regaddr);
228	      regval &= ~bit;
229	      putreg32(regval, regaddr);
230	    }
231	}
