233	/****************************************************************************
234	 * Name: up_enable_irq
235	 ****************************************************************************/
236	
237	void up_enable_irq(int irq)
238	{
239	  uintptr_t regaddr;
240	  uint32_t regval;
241	  uint32_t bit;
242	  int n;
243	
244	  DEBUGASSERT(irq >= NVIC_IRQ_NMI && irq < NR_IRQS);
245	
246	  if (irq >= NVIC_IRQ_FIRST)
247	    {
248	      /* The set-enable registers are write-1-to-set. */
249	
250	      n = irq - NVIC_IRQ_FIRST;
251	      putreg32((uint32_t)1 << (n & 0x1f), NVIC_IRQ_ENABLE(n));
252	
253	      /* The NVIC is not the only gate on this SoC.  Interrupt lines pass
254	       * through a per-CPU routing matrix in the system block first --
255	       * cpu0_int_0_31_en / cpu0_int_32_63_en -- and a line whose matrix bit
256	       * is clear never reaches the NVIC at all, no matter what the NVIC
257	       * enable says.  The Beken bootloader sets bit 4 (UART0) there as the
258	       * last step of bringing its console up and clears it again on the way
259	       * out, which is how this port booted to a shell whose transmit worked
260	       * while every received byte vanished: polled TX needs no interrupt,
261	       * RX does.  The bit index matches the NVIC line number.
262	       */
263	
264	      modifyreg32(BK7258_SYS_CPU0_INT_EN(n), 0, (uint32_t)1 << (n & 0x1f));
265	    }
266	  else if (bk7258_exception_bit(irq, &regaddr, &bit) == OK)
267	    {
268	      regval  = getreg32(regaddr);
269	      regval |= bit;
270	      putreg32(regval, regaddr);
271	    }
272	}
