291	#ifdef CONFIG_ARCH_IRQPRIO
292	int up_prioritize_irq(int irq, int priority)
293	{
294	  uintptr_t regaddr;
295	  uint32_t regval;
296	  int shift;
297	
298	  DEBUGASSERT(irq >= NVIC_IRQ_MEMFAULT && irq < NR_IRQS &&
299	              (unsigned)priority <= NVIC_SYSH_PRIORITY_MIN);
300	
301	  if (irq < NVIC_IRQ_FIRST)
302	    {
303	      /* The system handler priority registers start at exception 4. */
304	
305	      regaddr = NVIC_SYSH_PRIORITY(irq);
306	      irq    -= 4;
307	    }
308	  else
309	    {
310	      irq    -= NVIC_IRQ_FIRST;
311	      regaddr = NVIC_IRQ_PRIORITY(irq);
312	    }
313	
314	  shift   = ((irq & 3) << 3);
315	  regval  = getreg32(regaddr);
316	  regval &= ~((uint32_t)0xff << shift);
317	  regval |= ((uint32_t)priority << shift);
318	  putreg32(regval, regaddr);
319	
320	  return OK;
321	}
322	#endif /* CONFIG_ARCH_IRQPRIO */
