int irq_to_ndx(int irq)
{
  DEBUGASSERT(g_irqmap_count < CONFIG_ARCH_NUSER_INTERRUPTS);

  irqstate_t flags = spin_lock_irqsave(&g_irqlock);
  if (g_irqmap[irq] == 0)
    {
      int ndx = g_irqmap_count++;
      g_irqmap[irq] = ndx;
      g_irqrevmap[ndx] = irq;
    }

  spin_unlock_irqrestore(&g_irqlock, flags);
  return g_irqmap[irq];
}
